      "আজ সততার সাথে নেওয়া দীর্ঘমেয়াদি সিদ্ধান্ত যেকোনো পরিস্থিতিতে টিকে থাকবে।",
      "আজ যা কেউ খেয়াল করছে না, একদিন সবাই তার ওপরই নির্ভর করবে।",
