      "गती तेव्हाच सुरू होते जेव्हा तू ठरवतोस की ती सुरू व्हावी.",
      "भीतीशी वाटाघाटी करू नकोस. फक्त पुढे जा.",
      "प्रत्येक धाडसी गोष्ट अगदी आजसारख्याच एका दिवशी सुरू झाली होती.",
      "तू खोलीच्या मागे उभं राहण्यासाठी घडलेला नाहीस.",
